'use strict';
(function(root){
 const titles={shopping:['Oilaviy xaridlar','Ro‘zg‘or ro‘yxati barcha a’zolarda birga.'],more:['Yana imkoniyatlar','Kerakli bo‘limni tanlang.'],installments:['Nasiya va bo‘lib to‘lash','Qolgan to‘lovlar va muddatlar.'],remittances:['Xorijdan kelgan pul','Valyuta, komissiya va amalda olingan summa.'],meters:['Kommunal sarf daftari','Hisoblagich ko‘rsatkichlari va taxminiy sarf.'],seasonal:['Mavsumiy oilaviy budjet','Maqsadni tanlang va jamg‘arishni boshlang.'],personal:['Shaxsiy hamyon','Bu hisob faqat sizga ko‘rinadi.']};
 const country={UZ:['O‘zbekiston','UZS','+998','Asia/Tashkent'],KZ:['Qozog‘iston','KZT','+7','Asia/Almaty'],KG:['Qirg‘iziston','KGS','+996','Asia/Bishkek'],TJ:['Tojikiston','TJS','+992','Asia/Dushanbe'],TM:['Turkmaniston','TMT','+993','Asia/Ashgabat']};
 const child=()=>globalThis.barakaCloud?.household?.role==='child';
 function quick(){return `<section class="card life-quick"><h2>Tez xarajat</h2><form onsubmit="event.preventDefault();BarakaLife.parseQuick(this)"><label class="field">Nima va qancha?<input name="quick" required maxlength="120" placeholder="Bozor 180 ming" autocomplete="off"></label><button class="primary">Davom etish</button></form><small>Summa va toifani tekshirib tasdiqlaysiz.</small></section>`}
 function parseQuick(form){try{const x=BarakaData.quickExpense(form.elements.quick.value);openForm('transaction');for(const k of ['name','amount','category'])$('#fields [name='+k+']').value=x[k]}catch(e){toast(e.message)}}
 function runway(){const r=BarakaData.runway(state);return `<section class="card"><div class="card-head"><h2>Keyingi daromadgacha</h2><button class="text-button" onclick="openForm('income-date')">Sanani belgilash</button></div>${r?`<p>${prettyDate(r.end)} gacha · ${r.days} kun</p><div class="big-value ${r.remaining<0?'negative':''}">${cash(r.remaining)} <small>so‘m qoladi</small></div><p>Kuniga ${cash(r.daily)} so‘m · Rejalashtirilgan to‘lovlar: ${cash(r.reserved)} so‘m</p><small>Joriy qoldiqdan shu muddatgacha bo‘lgan to‘lovlar, qaytariladigan qarzlaringiz va nasiya ayrildi. Kelajakdagi kirim va yangi xarajatlar hisobga olinmagan.</small>`:'<p>Keyingi daromad sanasini belgilang. Qancha pul qolishini hisoblaymiz.</p>'}</section>`}
 function shopping(){return `<section class="card"><div class="card-head"><h2>Xarid ro‘yxati</h2><button class="primary" onclick="openForm('shopping-item')">＋ Mahsulot</button></div>${(state.shopping||[]).map(x=>`<div class="row"><button class="icon-button" aria-label="Olinganini belgilash" aria-pressed="${x.done}" onclick="BarakaLife.toggleShopping('${x.id}')">${x.done?'☑':'☐'}</button><div class="row-info"><b data-no-translate>${esc(x.name)}</b><small>${esc(x.quantity)} · ${esc(x.member)}</small></div>${x.transactionId?'<span class="badge good">Xarajat qayd etilgan</span>':!child()?`<button class="text-button" onclick="openForm('shopping-pay','${x.id}')">Summani qayd etish</button>`:''}<button class="icon-button" aria-label="Tahrirlash" onclick="openForm('shopping-item','${x.id}')">${icon('edit')}</button><button class="icon-button" aria-label="O‘chirish" onclick="BarakaLife.remove('shopping','${x.id}')">${icon('trash')}</button></div>`).join('')||empty('Ro‘yxat hali bo‘sh','Uyda kerakli mahsulotlarni qo‘shing; oila a’zolari o‘z telefonidan ko‘radi.')}</section>`}
 function toggleShopping(id){const x=state.shopping.find(x=>x.id===id);if(x){x.done=!x.done;save()}}
 const links=[['tasks','Rejalar'],['transactions','Amaliyotlar'],['wallets','Hamyonlar'],['personal','Shaxsiy hamyon'],['goals','Jamg‘armalar'],['seasonal','Mavsumiy budjet'],['debts','Qarzlar'],['installments','Nasiya'],['remittances','Xorijdan kelgan pul'],['bills','To‘lovlar'],['utilities','Kommunal hisoblar'],['meters','Kommunal sarf daftari'],['report','Hisobotlar'],['calendar','Taqvim'],['prayer','Namoz vaqtlari'],['transport','Transport'],['favorites','Saqlangan joylar'],['settings','Sozlamalar']];
 function more(){return `<div class="triple-grid">${links.filter(([id])=>!child()||['tasks','personal','settings'].includes(id)).map(([id,label])=>`<a class="card life-link" href="#${id}">${icon('arrow')}<h2>${label}</h2></a>`).join('')}</div>`}
 function installments(){return `<section class="card"><div class="card-head"><h2>Nasiya jadvali</h2><button class="primary" onclick="openForm('installment')">＋ Nasiya</button></div>${(state.installments||[]).map(x=>{const remaining=x.total-x.down-Array.from({length:x.paid},(_,i)=>BarakaData.installmentDue(x,i)).reduce((a,b)=>a+b,0);return `<div class="card section-gap"><div class="card-head"><h3>${esc(x.name)}</h3><button class="text-button" onclick="BarakaLife.remove('installments','${x.id}')">O‘chirish</button></div><p>Jami ${cash(x.total)} · Boshlang‘ich ${cash(x.down)} · Qolgan ${cash(remaining)} so‘m</p><p>${x.paid} / ${x.count} ta to‘lov qayd etilgan</p>${x.paid<x.count?`<button class="primary" onclick="BarakaLife.payInstallment('${x.id}')">${prettyDate(BarakaData.monthlyDate(x.date,x.paid))} · ${money(BarakaData.installmentDue(x))} so‘m to‘langanini qayd etish</button>`:'<span class="badge good">Yakunlangan</span>'}<details><summary>Barcha muddatlar</summary>${Array.from({length:x.count},(_,i)=>`<p>${i<x.paid?'✓':'○'} ${prettyDate(BarakaData.monthlyDate(x.date,i))} · ${cash(BarakaData.installmentDue(x,i))} so‘m</p>`).join('')}</details></div>`}).join('')||empty('Nasiya yo‘q')}</section>`}
 function payInstallment(id){const x=state.installments.find(x=>x.id===id);if(!x||x.paid>=x.count)return;const amount=BarakaData.installmentDue(x);confirmAction('To‘lov qayd etilsinmi?',`<p>${cash(amount)} so‘m xarajatga yoziladi. Bu bank to‘lovi emas.</p>`,()=>{addExpense(x.name,amount,x.walletId,'Xaridlar');x.paid++;save()})}
 function addExpense(name,amount,walletId,category='Boshqa',type='expense'){const w=state.wallets.find(w=>w.id===walletId);if(!w)throw Error('Hamyon topilmadi.');const id=uid();state.transactions.push({id,name,amount,walletId,category,type,member:globalThis.barakaCloud?.user?.name||state.members[0],method:w.type==='cash'?'Naqd':'Karta',date:day()});return id}
 function remittances(){return `<section class="card"><div class="card-head"><h2>Xorijdan kelgan pul</h2><button class="primary" onclick="openForm('remittance')">＋ Pul kelishi</button></div>${(state.remittances||[]).map(x=>`<div class="row"><div class="row-info"><b data-no-translate>${esc(x.name)}</b><small>${prettyDate(x.date)} · Asl: ${money(x.original/100)} ${x.currency} · Komissiya: ${money(x.fee/100)} ${x.currency}</small><small>Amaldagi kurs: ${money(x.received/(x.original/100))} so‘m / ${x.currency}</small></div><span class="row-amount">${cash(x.received)}<small>so‘m olindi</small></span></div>`).join('')||empty('Pul kelishi qayd etilmagan')}<p class="form-note">Amalda olingan so‘m summasi tanlangan hamyonga kirim sifatida yoziladi. Valyuta miqdori alohida saqlanadi; kurs avtomatik bank taklifi emas.</p></section>`}
 function meters(){const rows=[...(state.meterReadings||[])].sort((a,b)=>b.date.localeCompare(a.date));return `<section class="card"><div class="card-head"><h2>Hisoblagichlar</h2><button class="primary" onclick="openForm('meter')">＋ Ko‘rsatkich</button></div>${rows.map(x=>{const u=state.utilities.find(u=>u.id===x.utilityId),previous=rows.filter(p=>p.utilityId===x.utilityId&&p.date<x.date)[0],usage=previous?x.value-previous.value:null;return `<div class="row"><div class="row-info"><b data-no-translate>${esc(u?.name||'O‘chirilgan hisob')} · ${prettyDate(x.date)}</b><small>Ko‘rsatkich: ${money(x.value)} · Tarif: ${money(x.tariff)} so‘m / birlik</small>${usage!==null?`<p>Sarf: ${money(usage)} · Taxminiy summa: ${cash(usage*x.tariff)} so‘m</p>`:'<small>Sarfni hisoblash uchun oldingi ko‘rsatkich kerak.</small>'}${x.photo?`<img class="meter-photo" src="${x.photo}" alt="Hisoblagich surati" loading="lazy">`:''}</div><button class="text-button" onclick="BarakaLife.remove('meterReadings','${x.id}')">O‘chirish</button></div>`}).join('')||empty('Ko‘rsatkichlar yo‘q','Avval Kommunal xizmatlar bo‘limida abonent qo‘shing.')}<p class="form-note">Taxminiy hisob. Tarifni o‘zingiz kiritasiz; pog‘onali tarif, imtiyoz va operator qarzdorligi hisoblanmaydi. Bu bank to‘lovi yaratmaydi.</p></section>`}
 const templates=[['Maktabga tayyorgarlik','🎓'],['Qishki isitish','🏡'],['Uy ta’miri','🏡'],['To‘y','💍'],['Bayram xarajatlari','🎯'],['Favqulodda zaxira','🛟']];
 function seasonal(){return `<div class="triple-grid">${templates.map(([name,emoji],i)=>`<section class="card"><span class="goal-emoji">${emoji}</span><h2>${name}</h2><p>Summani va muddatni oilangizga mos belgilang.</p><button class="primary" onclick="BarakaLife.template(${i})">Reja yaratish</button></section>`).join('')}</div>`}
 function template(i){const t=templates[i];if(!t)return;openForm('goal');$('#fields [name=name]').value=t[0];$('#fields [name=icon]').value=t[1]}
 function settings(){return `<section class="card section-gap"><h2>Til va mintaqa</h2>${select('Interfeys tili','uiLanguage',[['uz','O‘zbek lotin'],['uz-Cyrl','Ўзбек кирилл'],['ru','Русский']],globalThis.BarakaLocale?.language||'uz').replace('<select ','<select onchange="BarakaLocale.set(this.value)" ')}${select('Mamlakat','country',Object.entries(country).map(([k,v])=>[k,v[0]]),state.settings.country).replace('<select ','<select onchange="BarakaLife.setCountry(this.value)" ')}<p class="section-text">${country[state.settings.country||'UZ'][1]} · ${country[state.settings.country||'UZ'][2]} · ${country[state.settings.country||'UZ'][3]}</p><p>Oilaviy moliya hozir so‘mda yuritiladi. Xorijiy valyutadagi pul “Xorijdan kelgan pul”da asl valyutasi bilan saqlanadi.</p><div class="settings-row"><div><h3>Telegram eslatmalari</h3><p>Ixtiyoriy umumiy eslatma. Balans va qarz tafsilotlari yuborilmaydi.</p></div><button class="secondary" onclick="BarakaLife.telegram()">Sozlash</button></div></section>`}
 function setCountry(value){if(country[value]){state.settings.country=value;save()}}
 function form(type,id){
 const wallets=()=>select('Hamyon','walletId',state.wallets.map(w=>[w.id,w.name]));
 if(type==='income-date')return {title:'Keyingi daromad sanasi',html:dateField('Sana',state.settings.nextIncomeDate||shiftDay(10))};
 if(type==='shopping-item'){const x=(state.shopping||[]).find(x=>x.id===id)||{};return {title:'Xarid mahsuloti',html:nameField('Nima kerak?',x.name||'',100)+field('Miqdor','quantity','text',x.quantity||'1','required maxlength="40"')+select('Kim oladi?','member',state.members.map(m=>[m,m]),x.member)}}
 if(type==='shopping-pay'){const x=state.shopping.find(x=>x.id===id);if(!x)return null;return {title:x.name+' xarajati',html:amountField('Haqiqiy summa (so‘m)','amount')+wallets()+select('Toifa','category',Object.keys(cats).map(c=>[c,c]),'Oziq-ovqat')}}
 if(type==='installment')return {title:'Yangi nasiya',html:nameField('Nomi','',80)+amountField('Jami narx (so‘m)','total')+amountField('Boshlang‘ich to‘lov (so‘m)','down',0,true)+field('Oylik to‘lovlar soni','count','number',12,'required min="1" max="120" step="1"')+dateField('Birinchi oylik to‘lov sanasi')+wallets()+'<p>Boshlang‘ich to‘lov saqlanganda xarajatga yoziladi. Oylik to‘lovlar alohida tasdiqlanadi.</p>'};
 if(type==='remittance')return {title:'Pul kelishini qayd etish',html:nameField('Kimdan / izoh','',80)+select('Asl valyuta','currency',['USD','EUR','RUB','KZT','KGS','TJS','TMT','UZS'].map(c=>[c,c]))+field('Yuborilgan miqdor','original','number','','required min="0.01" max="10000000000" step="0.01"')+field('Komissiya (shu valyutada)','fee','number',0,'required min="0" max="10000000000" step="0.01"')+amountField('Amalda olingan summa (so‘m)','received')+dateField('Olingan sana')+wallets()};
 if(type==='meter')return {title:'Hisoblagich ko‘rsatkichi',html:select('Abonent','utilityId',state.utilities.map(u=>[u.id,u.name]))+dateField('Ko‘rsatkich sanasi')+amountField('Ko‘rsatkich (butun birlik)','value','',true)+amountField('Bir birlik tarifi (so‘m)','tariff',0,true)+'<label class="field">Surat (ixtiyoriy)<input id="meter-photo-input" type="file" accept="image/jpeg,image/png,image/webp"></label><small>Surat kichraytirilib oilaviy hisobda saqlanadi.</small>'};
 return null;
 }
 function integer(v,min=0,max=1e12){const n=Number(v);if(v===''||!Number.isSafeInteger(n)||n<min||n>max)throw Error('Summa yoki son noto‘g‘ri.');return n}
 function commit(type,id,d){
 if(type==='income-date'){if(d.date<=day())throw Error('Kelajakdagi sanani tanlang.');state.settings.nextIncomeDate=d.date;return true}
 if(type==='shopping-item'){const old=state.shopping.find(x=>x.id===id);const x={id:id||uid(),name:d.name,quantity:d.quantity.trim(),member:d.member,done:old?.done||false,transactionId:old?.transactionId||''};if(!x.quantity)throw Error('Miqdorni kiriting.');if(id)state.shopping=state.shopping.map(y=>y.id===id?x:y);else state.shopping.push(x);return true}
 if(type==='shopping-pay'){const x=state.shopping.find(x=>x.id===id);if(!x||x.transactionId)throw Error('Bu xarid allaqachon qayd etilgan.');x.transactionId=addExpense(x.name,d.amount,d.walletId,d.category);x.done=true;return true}
 if(type==='installment'){const total=integer(d.total,1),down=integer(d.down),count=integer(d.count,1,120);if(down>=total||total-down<count)throw Error('Qolgan summa va to‘lovlar sonini tekshiring.');if(down)addExpense(d.name+' · boshlang‘ich',down,d.walletId,'Xaridlar');state.installments.push({id:uid(),name:d.name,total,down,count,paid:0,date:d.date,walletId:d.walletId});return true}
 if(type==='remittance'){const original=Math.round(Number(d.original)*100),fee=Math.round(Number(d.fee)*100),received=integer(d.received,1);integer(original,1);integer(fee);if(fee>original)throw Error('Komissiya yuborilgan puldan katta.');const transactionId=addExpense(d.name,received,d.walletId,'Boshqa','income');state.transactions.find(x=>x.id===transactionId).date=d.date;state.remittances.push({id:uid(),name:d.name,currency:d.currency,original,fee,received,date:d.date,transactionId});return true}
 if(type==='meter'){if(!state.utilities.some(u=>u.id===d.utilityId))throw Error('Avval abonent hisobini qo‘shing.');const value=integer(d.value),tariff=integer(d.tariff);if(state.meterReadings.some(x=>x.utilityId===d.utilityId&&x.date===d.date))throw Error('Bu sanada ko‘rsatkich bor.');const all=state.meterReadings.filter(x=>x.utilityId===d.utilityId);if(all.some(x=>x.date<d.date&&x.value>value||x.date>d.date&&x.value<value))throw Error('Ko‘rsatkichlar vaqt bo‘yicha kamaymasligi kerak.');state.meterReadings.push({id:uid(),utilityId:d.utilityId,value,tariff,date:d.date,photo:d.photo||''});return true}
 return false;
 }
 function remove(list,id){if(!['shopping','installments','meterReadings'].includes(list))return;confirmAction('Yozuv o‘chirilsinmi?','<p>Avval qayd etilgan pul amaliyotlari saqlanadi.</p>',()=>{state[list]=state[list].filter(x=>x.id!==id);save()})}
 async function photo(){const file=$('#meter-photo-input')?.files?.[0];if(!file)return '';if(file.size>10*1024*1024)throw Error('Surat 10 MB dan oshmasin.');const bitmap=await createImageBitmap(file);const c=document.createElement('canvas'),scale=Math.min(1,640/Math.max(bitmap.width,bitmap.height));c.width=bitmap.width*scale;c.height=bitmap.height*scale;c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);bitmap.close();let data=c.toDataURL('image/jpeg',.6);if(data.length>160000)throw Error('Surat juda katta. Kichikroq surat tanlang.');return data}
 let personalData=null;
 function personal(){return `<section class="card"><div class="card-head"><h2>Shaxsiy hisob</h2><button class="secondary" onclick="BarakaLife.loadPersonal()">Ochish / yangilash</button></div><div id="personal-content"><p>Serverdagi shaxsiy hisobingizni oching. Oilaning boshqa a’zolariga yuborilmaydi.</p></div></section>`}
 async function loadPersonal(){try{const data=await barakaCloud.request('/api/personal');personalData=data;paintPersonal()}catch(e){toast(e.message)}}
 function paintPersonal(){const el=$('#personal-content');if(!el||!personalData)return;const p=personalData.state;el.innerHTML=`<div class="big-value">${cash(p.wallets.reduce((a,w)=>a+w.opening,0)+p.transactions.reduce((a,x)=>a+(x.type==='income'?x.amount:-x.amount),0))} <small>so‘m</small></div><button class="primary" onclick="BarakaLife.personalForm()">＋ Shaxsiy amaliyot</button>${p.transactions.slice().reverse().map(x=>`<div class="row"><b data-no-translate>${esc(x.name)}</b><span class="row-amount">${x.type==='income'?'+':'−'}${cash(x.amount)}</span></div>`).join('')}`}
 function personalForm(){if(!personalData)return;formType='personal-entry';setModal('Shaxsiy amaliyot',nameField('Izoh')+amountField('Summa (so‘m)','amount')+select('Turi','type',[['expense','Xarajat'],['income','Kirim']]))}
 async function personalSubmit(d){if(!personalData)throw Error('Shaxsiy hisobni qayta oching.');const next=structuredClone(personalData.state);next.transactions.push({id:uid(),name:d.name,amount:d.amount,type:d.type,category:'Boshqa',member:barakaCloud.user.name,date:day(),walletId:next.wallets[0].id,method:'Naqd'});try{personalData=await barakaCloud.request('/api/personal','PUT',{revision:personalData.revision,state:next});closeModal();paintPersonal();toast('Shaxsiy hisob saqlandi')}catch(e){$('#form-error').textContent=e.message}}
 async function telegram(){try{const info=await barakaCloud.request('/api/telegram');setModal('Telegram eslatmalari',info.configured?`<p>${info.enabled?'Eslatmalar yoqilgan.':'Botni o‘z Telegram hisobingizga ulang.'} Faqat umumiy eslatma yuboriladi.</p><button type="button" class="primary" onclick="BarakaLife.saveTelegram('pair')">Botni ulash</button><button type="button" class="secondary" onclick="BarakaLife.saveTelegram('off')">O‘chirish</button>`:'<p>Telegram operatori hali sozlanmagan. Administrator bot tokeni va bot nomini serverga ulashi kerak.</p>',false)}catch(e){toast(e.message)}}
 async function saveTelegram(action){try{const result=await barakaCloud.request('/api/telegram','POST',action==='off'?{enabled:false}:{action});if(action==='pair'){setModal('Telegram botga ulash',`<p>Havolani oching, botda Start tugmasini bosing, keyin bu oynaga qaytib tasdiqlang. Havola 10 daqiqa amal qiladi.</p><a class="primary" href="${esc(result.url)}" target="_blank" rel="noopener noreferrer">Telegramni ochish</a><button type="button" class="secondary" onclick="BarakaLife.saveTelegram('verify')">Start bosdim — tekshirish</button>`,false)}else{closeModal();toast('Telegram sozlamasi saqlandi')}}catch(e){toast(e.message)}}

 root.BarakaLife={titles,views:{shopping,more,installments,remittances,meters,seasonal,personal},quick,runway,parseQuick,toggleShopping,payInstallment,template,settings,setCountry,form,commit,remove,photo,loadPersonal,personalForm,personalSubmit,telegram,saveTelegram,child};
})(globalThis);
